// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz parameters: actor address and an arbitrary unlockTime and deposit value
    function testFuzz_property(address actor, uint256 unlockTime, uint256 deposit) public {
        // keep deposit in a reasonable range but allow zero and large values
        deposit = bound(deposit, 0, 10 ether);
        // actor must be non-zero
        vm.assume(actor != address(0));

        // fund the actor so they can send deposit
        vm.deal(actor, deposit);

        // call Put as the actor with the fuzzed unlockTime and deposit
        vm.prank(actor);
        bool ok;
        // call within try/catch to observe behavior but we expect Put to succeed
        try c.Put{value: deposit}(unlockTime) {
            ok = true;
        } catch {
            ok = false;
        }

        // read the recorded unlockTime for the actor from the public mapping
        (uint256 recordedUnlockTime, uint256 recordedBalance) = c.Acc(actor);

        // The universal property: if the Put call succeeded, the recorded unlockTime is >= block.timestamp
        // (reference C enforces this for all inputs; mutant can produce recordedUnlockTime < now for some inputs)
        if (ok) {
            assertTrue(recordedUnlockTime >= block.timestamp);
        } else {
            // If the call reverted, we still assert consistency: balance must be unchanged (0)
            // but per instructions we must have exactly one assertTrue that distinguishes; so in revert case
            // we assert the same invariant vacuously by checking recordedUnlockTime >= block.timestamp
            // (Put reverting should not produce a mapping entry with unlockTime < now)
            assertTrue(recordedUnlockTime >= block.timestamp);
        }
    }
}

