pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: depositor address and desired unlock time
    function testFuzz_property(address actor, uint256 _unlockTime, uint256 deposit) public {
        // keep actor non-zero to be a sensible caller
        vm.assume(actor != address(0));
        // bound deposit to a reasonable range but allow wide variety (including zero)
        deposit = deposit % 10 ether;
        // give the actor enough balance to send
        vm.deal(actor, deposit);

        // record current time
        uint256 nowBefore = block.timestamp;

        // perform Put as the actor with the fuzzed unlockTime and deposit
        vm.prank(actor);
        if (deposit > 0) {
            c.Put{value: deposit}(_unlockTime);
        } else {
            // even if deposit is zero, the call is allowed; call without value
            c.Put(_unlockTime);
        }

        // The reference implementation always sets Acc[actor].unlockTime >= block.timestamp
        // Assert that invariant: recorded unlockTime is not less than current block.timestamp
        // Use the public getter for Acc (auto-generated). Acc(actor).unlockTime is accessible
        (uint256 recordedUnlockTime, uint256 recordedBalance) = getAcc(actor);
        // single assertion reading c's public surface
        assertTrue(recordedUnlockTime >= block.timestamp);
    }

    // helper to read the public struct mapping since solidity auto-generated getter for mapping returns tuple (unlockTime, balance)
    function getAcc(address a) internal view returns (uint256, uint256) {
        return c.Acc(a);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz parameters: actor who calls Put, the deposit value, and the supplied _unlockTime
    function testFuzz_property(address actor, uint256 deposit, uint256 suppliedUnlock) public {
        // keep actor as a non-zero address (EOA) and deposit in a reasonable bound so vm.deal works
        vm.assume(actor != address(0));
        deposit = bound(deposit, 1, 10 ether);

        // Fund the actor and perform the call at current block timestamp
        vm.deal(actor, deposit);
        vm.prank(actor);

        // record block.timestamp before call
        uint256 before = block.timestamp;

        // perform the payable call Put(suppliedUnlock) from actor with deposit
        // use low-level try/catch style not needed here but keep straightforward call
        // Make the call; it should not revert in the reference for these params
        c.Put{value: deposit}(suppliedUnlock);

        // After the call, read the stored unlockTime for actor via the public mapping getter
        (uint256 recordedUnlock,,,,) = getHolder(actor);

        // The reference guarantees recordedUnlock >= before; the mutant that assigns raw _unlockTime
        // can record a value < before for some suppliedUnlock (e.g., a past timestamp).
        assertTrue(recordedUnlock >= before);
    }

    // helper to read the Holder struct via public mapping getters generated by the compiler
    // The original contract's mapping is: mapping (address => Holder) public Acc;
    // Solidity generates a getter: function Acc(address) returns (uint unlockTime, uint balance)
    // But since structure ordering may vary in the test environment, provide a thin wrapper that calls c.Acc
    function getHolder(address a) internal view returns (uint256 unlockTime, uint256 balance, address dummy1, address dummy2, uint256 dummy3) {
        // We can only call the public getter c.Acc(a) which returns (uint,uint).
        // To satisfy the tuple unpacking above, return extra dummy values.
        (unlockTime, balance) = c.Acc(a);
        return (unlockTime, balance, address(0), address(0), uint256(0));
    }
}

