pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address actor, uint256 unlockTime, uint256 deposit) public {
        // Keep deposit reasonable (can't exceed uint128 for EVM balance concerns) but wide
        deposit = bound(deposit, 0, 10 ether);
        // actor should not be zero address to be a normal caller
        vm.assume(actor != address(0));

        // We are testing the rule: if the caller supplies an unlockTime strictly in the future
        // (relative to the block timestamp at call time), then after Put returns the stored
        // unlockTime for that caller equals the supplied unlockTime. The reference contract
        // enforces this by clamping to now only when _unlockTime <= now, preserving future times.
        // The mutant that unconditionally assigns acc.unlockTime = _unlockTime can set an
        // unlockTime in the past; however this property focuses on preserving future values.

        // Arrange: give the actor some ETH and make the call as them
        vm.deal(actor, deposit);
        vm.prank(actor);

        // Capture current block.timestamp to check the precondition
        uint256 nowTs = block.timestamp;

        // Only consider the admissible domain where the fuzzed unlockTime is strictly in the future
        vm.assume(unlockTime > nowTs);

        // Act: call Put as the actor with the fuzzed unlockTime and deposit
        bool ok;
        try c.Put{value: deposit}(unlockTime) {
            ok = true;
        } catch {
            ok = false;
        }

        // We require the call to succeed on the reference for these inputs; if it reverts then
        // the input is inadmissible for our intended universal property. Ensure it succeeded.
        vm.assume(ok);

        // Assert: for the reference, when _unlockTime > now, the stored unlockTime must equal _unlockTime
        (uint256 recordedUnlockTime, uint256 recordedBalance) = c.Acc(actor);
        // Single assertion required: recordedUnlockTime equals the provided future unlockTime
        assertTrue(recordedUnlockTime == unlockTime);
    }
}

