    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _unlockTime, uint256 sendAmt, address actor) public {
        // Keep inputs in wide, sensible bounds
        vm.assume(actor != address(0));
        // limit sendAmt to a reasonable range to avoid out-of-gas in test environment
        sendAmt = bound(sendAmt, 0, 10 ether);
        // make sure actor has funds to send
        vm.deal(actor, sendAmt);

        // ensure timestamp is something predictable; advance to a known time
        vm.warp(block.timestamp + 1);
        uint256 before = block.timestamp;

        // Actor calls Put with fuzzed unlockTime and sends fuzzed amount
        vm.prank(actor);
        if (sendAmt > 0) {
            c.Put{value: sendAmt}(_unlockTime);
