contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: futureUnlock is the candidate future unlock time, payer is the caller, value is ether to send
    function testFuzz_property(uint256 futureUnlock, address payer, uint256 value) public {
        // Keep domains reasonable and admissible
