        uint256 _future = bound(futureUnlock, block.timestamp, type(uint256).max);
        // avoid zero-address payer which is allowed but indistinguishable; keep wide
        vm.assume(payer != address(0));
        // bound value to a practical range and ensure at least 1 wei to change balance
        uint256 _value = bound(value, 1, 1 ether * 1000);

        // fund payer so they can send value
        vm.deal(payer, _value);

        // call Put from payer with _future and _value
        vm.prank(payer);
        c.Put{value: _value}(_future);

        // read stored unlockTime for payer
        (uint unlockTime,) = getHolder(payer);

        // The correct contract stores max(_future, block.timestamp). At call return, block.timestamp is the same as used in Put.
        // Since we ensured _future >= block.timestamp via bound above, the stored unlockTime should equal _future for the correct contract.
        // The mutant that always sets acc.unlockTime = block.timestamp will make unlockTime < _future for some inputs; therefore
        // assert that stored unlockTime is >= _future. This will hold for the reference for all admissible inputs, and fail on the mutant
        // whenever _future > block.timestamp.
        assertTrue(unlockTime >= _future);
    }

    // helper to read the public mapping Acc (auto-generated getter has signature Acc(address) returns (uint unlockTime, uint balance))
    function getHolder(address a) internal view returns (uint,uint) {
        return c.Acc(a);
    }
}

