import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz the sender and the deposit amount; the rule: after Put, Acc[sender].balance >= previous balance
    function testFuzz_property(address sender, uint256 amt) public {
        vm.assume(sender != address(0));
        // keep amt wide but bounded to avoid meaningless extremes in the environment
        uint256 value = bound(amt, 0, type(uint128).max);

        // record previous balance from the contract's public getter
        // Acc is public mapping of Holder; its autogenerated getter returns (unlockTime, balance)
        (uint256 beforeUnlock, uint256 beforeBal) = c.Acc(sender);

        // fund the sender externally so it can send value
        vm.deal(sender, value);
        vm.prank(sender);
        // perform the Put call with some unlockTime (use block.timestamp to keep routine simple)
        // use value as msg.value
        bool ok;
        try c.Put{value: value}(block.timestamp + 1) {
            ok = true;
        } catch {
            ok = false;
        }
        // We do not assert on ok (some edge cases may revert), but we assert the universal invariant:
        // After Put completes (or reverts), the stored balance must be >= previous stored balance for the reference contract.
        // For the reference contract this holds for all inputs; the mutant that removed the overflow check can wrap
        // and produce a smaller stored balance for some inputs and thus violate the property.

        (uint256 afterUnlock, uint256 afterBal) = c.Acc(sender);

        // exactly one assertion: stored balance must be >= previous stored balance
        assertTrue(afterBal >= beforeBal);
    }
}

