pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 priorBalance, uint256 deposit, uint256 unlockTime, address actor) public {
        // keep values wide but sensible
        vm.assume(actor != address(0));
        // fund actor so they can send deposit
        uint256 fund = deposit > 0 ? deposit : 1;
        vm.deal(actor, fund);

        // initialize stored balance for actor by directly manipulating via Put calls from actor
        // we perform multiple deposits to reach priorBalance by chunking (bounded) to avoid huge loops
        // but to set Acc[actor].balance to a specific priorBalance we use a helper: perform one Put with value = priorBalance
        // If priorBalance is 0, that's fine.
        vm.startPrank(actor);
        // make sure actor has enough ETH to set prior balance
        vm.deal(actor, priorBalance + deposit + 1);
        // initial set to priorBalance
        c.Put{value: priorBalance}(unlockTime);
        // record before
        uint256 before = c.Acc(actor).balance;
        // sanity: before should equal priorBalance (mod 2^256) on reference contract
        // now perform the test deposit which may trigger overflow on mutant
        bool ok;
        try c.Put{value: deposit}(unlockTime) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // read after
        uint256 after = c.Acc(actor).balance;

        // General invariant: on the correct contract, after >= before (no wrap-around decrease)
        // We assert that this holds. The mutant that removed the require can cause wrap-around so after < before
        assertTrue(after >= before);
    }
}

