import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: priorBalance and msgValue
    function testFuzz_property(uint256 priorBalance, uint256 msgValue) public {
        // keep values in wide but sensible domain
        vm.assume(priorBalance < type(uint256).max);
        vm.assume(msgValue <= type(uint256).max);

        address actor = address(0xABCD);
        // fund the actor externally so they can send msgValue
