        // initialize to known zero state, then set balance to target by one call
        vm.prank(actor);
        c.Put{value: target}(0);

        // read balance before the fuzzed Put
        uint256 before = c.Acc(actor).balance;

        // perform the fuzzed Put call sending msgValue
        vm.prank(actor);
        c.Put{value: msgValue}(0);

        uint256 afterBal = c.Acc(actor).balance;

        // General property: after >= before (no overflow) on correct contract; mutant that removed require can wrap so after < before
        assertTrue(afterBal >= before);
    }
