    function setUp() public { c = new C(address(this)); }

    // Fuzzed parameters: actor (who will Put funds) and amount to attempt to Collect.
    // General rule: if the stored balance for actor is < MinSum, then Collect must not succeed in transferring value.
    // We create a scenario where actor has a stored balance < MinSum and then try to Collect; reference preserves funds, mutant may allow transfer.
    function testFuzz_property(address actor, uint256 putAmount, uint256 collectAmount, uint256 warpTime) public {
        // keep actor non-zero
        vm.assume(actor != address(0));
        // clamp putAmount to small values to allow creating balances < MinSum and >0
        putAmount = bound(putAmount, 0, 1 ether - 1);
        // collectAmount at least 1 and bounded reasonably
        collectAmount = bound(collectAmount, 1, 1 ether);
        // ensure warpTime is some future or current time
        warpTime = bound(warpTime, block.timestamp, block.timestamp + 1000);

        // Fund the actor externally so they can Put
        vm.deal(actor, putAmount);

        // actor does Put with putAmount (may be zero)
        vm.prank(actor);
        c.Put{value: putAmount}(warpTime);

        // Read stored balance via public getter Acc(actor).balance is not directly available as a tuple in solidity test code,
        // but mapping Acc is public so Acc(actor) returns (unlockTime, balance) tuple; capture via call to getter.
        (uint256 storedUnlock, uint256 storedBalance) = c.Acc(actor);

        // Precondition we target: storedBalance < MinSum
        // If it's not < MinSum then this test's distinguishing property doesn't apply; skip via assume so fuzz picks other inputs.
        vm.assume(storedBalance < c.MinSum());

        // Advance time beyond unlock so Collect's time check passes
        vm.warp(storedUnlock + 1);

        // Ensure actor has enough external funds to receive (not required but safe)
        vm.deal(actor, address(actor).balance + collectAmount);

        // Try to call Collect as the actor and observe whether the call succeeded in sending funds.
        bool ok;
        vm.prank(actor);
        try c.Collect(collectAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract guarantees that if storedBalance < MinSum then Collect cannot transfer funds (so either it doesn't execute send or call will revert/return false).
        // We therefore assert that the call did NOT succeed in transferring funds (ok == false OR stored balance unchanged).
        // To observe state via public surface, re-read stored balance from the contract.
        (, uint256 afterBalance) = c.Acc(actor);

        // Single assertion that the reference always satisfies: either Collect did not succeed (ok == false) OR balance was not decreased
        // For the correct contract this is always true; the mutant removing MinSum may allow ok == true and afterBalance < storedBalance for some inputs.
        assertTrue((ok == false) || (afterBalance >= storedBalance));
    }
}

